output_schema:
Security vulnerabilities and logic errors with remediation guidance
{
  "security_issues": [
    {
      "id": "string - e.g., SEC-001",
      "severity": "critical | high | medium | low",
      "category": "string - OWASP category",
      "title": "string",
      "location": {
        "file": "string",
        "line": "number",
        "code": "string"
      },
      "description": "string - What the vulnerability is",
      "attack_vector": "string - How it could be exploited",
      "remediation": {
        "description": "string - How to fix",
        "code_example": "string - Secure alternative"
      },
      "references": ["string - CWE, OWASP links"]
    }
  ],
  "logic_errors": [
    {
      "id": "string - e.g., LOGIC-001",
      "severity": "critical | high | medium | low",
      "title": "string",
      "location": {
        "line": "number",
        "code": "string"
      },
      "description": "string - What the error is",
      "impact": "string - What could go wrong",
      "fix": "string - How to correct"
    }
  ],
  "edge_cases": [
    {
      "scenario": "string - The edge case",
      "location": "string",
      "current_behavior": "string - What happens now",
      "recommended_handling": "string - How to handle"
    }
  ],
  "test_coverage_gaps": [
    {
      "area": "string - What's not tested",
      "risk": "string - Why it matters",
      "suggested_tests": ["string - Test cases to add"]
    }
  ],
  "summary": {
    "critical_count": "number",
    "high_count": "number",
    "medium_count": "number",
    "low_count": "number",
    "blocks_merge": "boolean",
    "requires_security_team": "boolean"
  }
}
